 $('#active').textContent=state.jobs.filter(active).length;const nums=k=>state.gpus.map(g=>Number(g[k])).filter(Number.isFinite);const power=nums('power'),temps=nums('temp');$('#power').textContent=power.length?`${power.reduce((a,b)=>a+b,0).toFixed(0)} W`:'—';$('#temperature').textContent=temps.length?`${Math.max(...temps)} °C`:'—';$('#ram').textContent=`${(state.memory.used/2**30).toFixed(1)} / ${(state.memory.total/2**30).toFixed(1)} GB`;$('#uptime').textContent=`Üzemidő: ${Math.floor(state.uptime/3600)} óra ${Math.floor(state.uptime/60)%60} perc`;
