function openWallet(w){const f=$('#wallet-form');f.reset();f.elements.id.value=w?.id||newLocalId();if(w)for(const [k,v]of Object.entries(w))if(f.elements[k])f.elements[k].value=v;$('#wallet-error').textContent='';$('#wallet-dialog').showModal();closeCoinMenu();syncCoinPreview();void loadCoinCatalogue().then(syncCoinPreview).catch(()=>{$('#coin-picker-help').textContent='A coinlista nem tölthető be. A coinjelölést kézzel is megadhatod.';});}
function renderWatchdog(){const w=state.watchdog;if(!w)return;const t=w.temperature;$('#cpu-temperature').textContent=typeof t.celsius==='number'?`${t.celsius.toLocaleString('hu-HU',{maximumFractionDigits:1})} °C`:'— °C';$('#cpu-temperature-source').textContent=t.available?`Legmelegebb CPU-szenzor: ${t.source}`:t.error;$('#watchdog-phase').textContent=({disabled:'Kikapcsolva',monitoring:'Figyelés aktív',hot:'Hőhatár felett',cooling:'Visszahűlésre vár',latched:'Hővédelmi tiltás',sensor_error:'Hőmérő nem elérhető',error:'Watchdog-hiba'})[w.phase]||w.phase;if(!watchdogFormLoaded){const f=$('#watchdog-form');for(const [k,v]of Object.entries(w.config)){if(k==='enabled')f.elements[k].checked=v;else f.elements[k].value=v;}watchdogFormLoaded=true;}$('#watchdog-rearm').disabled=!w.latched;$('#watchdog-cancel').hidden=!w.pending.length;$('#watchdog-events').textContent=w.events.slice(-6).map(e=>`${new Date(e.at).toLocaleString('hu-HU')} · ${e.message}`).join('\n')||'Még nincs watchdog-esemény.';}
function renderGpus(){const list=$('#gpu-list');list.replaceChildren();for(const g of state.gpus){const c=el('article',undefined,'gpu-card'),head=el('div',undefined,'gpu-head');head.append(el('h3',`GPU ${g.index} · ${g.name}`),el('span',`${g.usage}% terhelés`,'badge'));c.append(head,el('div','PCI: '+(g.bus||'Nem olvasható')+' · VBIOS: '+(g.vbios||'Nem olvasható'),'uuid'),el('p','Az OC-sablont VBIOS-verzió alapján mentjük, a kártyatípus és a VRAM egyezésének ellenőrzésével.','hint'));const stats=el('div',undefined,'gpu-stats');for(const [name,value] of [['Hőmérséklet',`${g.temp} °C`],['Fogyasztás',`${g.power} / ${g.limit} W`],['VRAM',`${g.used} / ${g.total} MiB`],['GPU / memória',`${g.core} / ${g.memoryClock} MHz`]]){const s=el('div');s.append(el('strong',value),el('span',name));stats.append(s);}c.append(stats);c.append(btn('OC beállítások',()=>openOc(g),'ghost'));list.append(c);}}
function renderLog(){const j=state?.jobs.find(j=>j.id===$('#log-profile').value);$('#log-output').textContent=j?.logs.join('\n')||'Ehhez a profilhoz még nincs bányásznapló.';}
function catalogKey(id){return'catalog:'+id;}
function minerInfo(id){if(session.engines[id])return{...session.engines[id],supported:true,id};const item=minerCatalog.find(x=>catalogKey(x.id)===id);if(!item)return null;const platforms=Object.entries(item.platform||{}).filter(([,enabled])=>enabled).map(([name])=>name.toUpperCase());return{id,label:item.name,kind:item.platform?.cpu&&!item.platform?.amd&&!item.platform?.nvidia?'cpu':'gpu',algorithms:(item.algos||[]).map(a=>a.id),algorithmDetails:item.algos||[],platforms,versions:item.versions||[],supported:false};}
function algorithmKeys(id,info){const key=String(id).toLocaleLowerCase(),keys=new Set([key]),detail=info?.algorithmDetails?.find(item=>item.id===id);if(detail?.algo)keys.add(String(detail.algo).toLocaleLowerCase());const aliases={'rx/0':'randomx',ghostrider:'gr','cn-heavy/xhv':'cryptonight-xhv'};if(aliases[key])keys.add(aliases[key]);return keys;}
function algorithmCoins(id,info){const keys=algorithmKeys(id,info),coins=new Set();for(const item of algorithmCatalog)if(keys.has(String(item.algo).toLocaleLowerCase()))for(const coin of item.coins||[])coins.add(coin);return[...coins];}
function compatibleAlgorithms(info,coin){if(!info)return[];if(!coin)return info.algorithms||[];return(info.algorithms||[]).filter(id=>algorithmCoins(id,info).some(code=>code.toLocaleLowerCase()===coin.toLocaleLowerCase()));}
