function poolEndpointOptions(pool,coin,tls=false){const poolKey=String(pool).toLocaleLowerCase(),coinKey=String(coin).toLocaleLowerCase(),match=poolEndpointCatalog.find(item=>String(item.pool).toLocaleLowerCase()===poolKey&&String(item.coin).toLocaleLowerCase()===coinKey),options=[];for(const server of match?.servers||[]){const urls=tls?(server.ssl_urls||[]):(server.urls||[]);for(const url of urls)options.push({url,label:`${server.geo||'Automatikus'} · ${url}${tls?' · SSL':''}`});}if(!tls&&!options.length){const url=verifiedPoolEndpoints[`${poolKey}:${String(coin).toLocaleUpperCase()}`];if(url)options.push({url,label:`Alapértelmezett · ${url}`});}return options.filter((item,index,list)=>list.findIndex(other=>other.url===item.url)===index);}
