function populateMinerSelect(select,selected,coin=''){select.replaceChildren();select.dataset.compatibilityFallback='false';select.title='';const installed=el('optgroup');installed.label='Telepített és futtatható';for(const[id,info]of Object.entries(session.engines)){if(coin&&!compatibleAlgorithms({...info,supported:true,id},coin).length)continue;const option=el('option',info.label);option.value=id;installed.append(option);}if(installed.children.length)select.append(installed);const catalogue=el('optgroup');catalogue.label='További miner-katalógus · adapter szükséges';for(const item of minerCatalog.filter(x=>!['srbminer','lolminer','xmrig','xmrig-new'].includes(x.id))){const id=catalogKey(item.id),info=minerInfo(id);if(coin&&!compatibleAlgorithms(info,coin).length)continue;const platforms=Object.entries(item.platform||{}).filter(([,enabled])=>enabled).map(([name])=>name.toUpperCase()).join('/');const option=el('option',item.name+(platforms?' · '+platforms:''));option.value=id;catalogue.append(option);}if(catalogue.children.length)select.append(catalogue);if(!select.options.length&&coin){populateMinerSelect(select,selected,'');select.dataset.compatibilityFallback='true';select.title='Nincs kompatibilis katalógustalálat; az összes miner közül választhatsz.';return;}if(!select.options.length){const option=el('option','Nincs elérhető miner');option.value='';option.disabled=true;select.append(option);}select.value=selected;if(!select.value)select.value=select.querySelector('option:not(:disabled)')?.value||'';}
function engineChanged(){const f=$('#profile-form'),engine=f.elements.engine.value,info=minerInfo(engine);f.elements.algorithm.replaceChildren();for(const a of info?.algorithms||[]){const detail=info.algorithmDetails?.find(d=>d.id===a),hardware=detail&&info.supported?[detail.amd?'AMD':null,detail.nvidia?'NVIDIA':null,detail.intel?'Intel':null].filter(Boolean).join(' / '):'';const o=el('option',a+(hardware?' · '+hardware:''));o.value=a;f.elements.algorithm.append(o);}const cpuOnly=info?.supported?(info.algorithmDetails||[]).filter(a=>!a.amd&&!a.nvidia&&!a.intel):[];if(cpuOnly.length){const group=el('optgroup');group.label='Csak CPU · ebben a GPU-profilban nem használható';group.disabled=true;for(const a of cpuOnly){const o=el('option',a.id+' · CPU-only');o.value=a.id;group.append(o);}f.elements.algorithm.append(group);}const cpu=info?.kind==='cpu';$('#threads-label').hidden=!cpu;$('#devices-label').hidden=cpu;f.elements.threads.max=state.threads;$('#profile-save').disabled=!info?.supported;$('#profile-save-copy').disabled=!info?.supported;if(!info?.supported){const versions=info?.versions.length?' · verziók: '+info.versions.join(', '):'',platforms=info?.platforms.length?' · platform: '+info.platforms.join('/'):' ';$('#engine-help').textContent=`${info?.label||'Ismeretlen miner'}${platforms}${versions}. A választás megtekinthető, de mentéshez külön LocalForge futtatási adapter és telepítés szükséges.`;return;}const binary=engine==='srbminer'?'SRBMiner-MULTI':'lolMiner';$('#engine-help').textContent=engine==='xmrig'?'CPU-profil. Egyszerre egy CPU-profil futhat.':`GPU-profil. A miner saját eszközsorszámait használd; ezek eltérhetnek az nvidia-smi indexeitől. Ellenőrzés SSH-n: /opt/localforge/miners/${binary} --list-devices`;}
