function gpuBus(value){if(typeof value!=='string')return null;const m=value.match(/^(?:[0-9a-f]{4,8}:)?([0-9a-f]{1,2}):[0-9a-f]{2}\.[0-7]$/i);return m?m[1].toLowerCase().padStart(2,'0'):/^[0-9a-f]{1,2}$/i.test(value)?value.toLowerCase().padStart(2,'0'):null;}
